            op=rng.choice(['store','store','store','load','load','fence','xchg'])
            if op=='store': prog.append(['store',addr,w,rng.randint(0,(1<<(8*w))-1)])
            elif op=='load': prog.append(['load',addr,w])
            elif op=='fence': prog.append(['fence'])
            else: prog.append(['xchg',addr,w,rng.randint(0,(1<<(8*w))-1)])
        threads.append(prog)
    req={'memory':[rng.randint(0,255) for _ in range(memsz)],'threads':threads}
    t0=time.time(); r=solve(req); d=time.time()-t0
    if d>worst: worst=d; worstreq=req; print(f'trial {trial}: {d:.3f}s, {len(r["outcomes"])} outcomes')
print('WORST', worst)
print(json.dumps(worstreq)[:300])
